//go:build integration

package store

// Merge-on-renewal for correspondents' keys, against the real store under RLS
// (#795, ADR-040). Every key here is generated by go-crypto; the renewed and
// revoked copies are produced by go-crypto's own signing.

import (
	"bytes"
	"context"
	"testing"
	"time"

	"github.com/ProtonMail/go-crypto/openpgp"
	"github.com/ProtonMail/go-crypto/openpgp/packet"

	"mailroom/internal/pgpkeys"
)

const lcDay = 24 * time.Hour

func lcGenKey(t *testing.T, email string, created time.Time, lifetime time.Duration) *openpgp.Entity {
	t.Helper()
	e, err := openpgp.NewEntity("Lifecycle", "", email, &packet.Config{
		Algorithm: packet.PubKeyAlgoEdDSA, Curve: packet.Curve25519,
		Time:            func() time.Time { return created },
		KeyLifetimeSecs: uint32(lifetime / time.Second),
	})
	if err != nil {
		t.Fatalf("NewEntity: %v", err)
	}
	return e
}

func lcPub(t *testing.T, e *openpgp.Entity) []byte {
	t.Helper()
	var buf bytes.Buffer
	if err := e.Serialize(&buf); err != nil {
		t.Fatalf("Serialize: %v", err)
	}
	return buf.Bytes()
}

func lcFpr(t *testing.T, pub []byte) string {
	t.Helper()
	k, err := pgpkeys.Parse(pub)
	if err != nil {
		t.Fatalf("Parse: %v", err)
	}
	return k.Fingerprint
}

// lcRenew re-signs every identity and subkey of e at `at` with a lifetime of
// `life` from each key's creation — the shape pgpkeyd.Extend produces.
func lcRenew(t *testing.T, e *openpgp.Entity, at time.Time, life time.Duration) {
	t.Helper()
	cfg := &packet.Config{Time: func() time.Time { return at }}
	l := uint32(life / time.Second)
	for name, ident := range e.Identities {
		cp := *ident.SelfSignature
		cp.Notations = append([]*packet.Notation(nil), ident.SelfSignature.Notations...)
		cp.CreationTime, cp.KeyLifetimeSecs, cp.SigLifetimeSecs = at, &l, nil
		if err := cp.SignUserId(name, e.PrimaryKey, e.PrivateKey, cfg); err != nil {
			t.Fatal(err)
		}
		ident.SelfSignature = &cp
		ident.Signatures = append(ident.Signatures, &cp)
	}
	for i := range e.Subkeys {
		sub := &e.Subkeys[i]
		cp := *sub.Sig
		cp.Notations = append([]*packet.Notation(nil), sub.Sig.Notations...)
		cp.CreationTime, cp.KeyLifetimeSecs, cp.SigLifetimeSecs = at, &l, nil
		if err := cp.SignKey(sub.PublicKey, e.PrivateKey, cfg); err != nil {
			t.Fatal(err)
		}
		sub.Sig = &cp
	}
}

// TestContactKeyRenewalIsMerged is #795's bug, at the store: a correspondent's
// renewed key (same fingerprint) must replace the expiring copy's usability —
// by merging — without moving the pin, and a replay of the old copy, or of the
// pre-revocation copy, must not undo either.
func TestContactKeyRenewalIsMerged(t *testing.T) {
	f := newContactKeyFixture(t)
	ctx := context.Background()
	const addr = "renewer@example.com"
	contact := f.seedContact(t, addr)
	now := time.Now().UTC().Truncate(time.Second)

	e := lcGenKey(t, addr, now.Add(-300*lcDay), 310*lcDay) // expires in 10 days
	old := lcPub(t, e)
	fpr := lcFpr(t, old)
	lcRenew(t, e, now.Add(-time.Hour), 3*365*lcDay)
	renewed := lcPub(t, e)

	upsert := func(pub []byte, src string) bool {
		t.Helper()
		var created bool
		if err := f.st.UserTx(ctx, f.userID, func(tx *UserTx) error {
			var e error
			created, e = tx.UpsertContactKey(ctx, ContactKeyRow{
				ContactID: contact, Kind: KeyPGP, Fingerprint: fpr, PublicKey: pub, Source: src,
			})
			return e
		}); err != nil {
			t.Fatalf("upsert: %v", err)
		}
		return created
	}
	stored := func() ContactKey {
		t.Helper()
		var keys []ContactKey
		if err := f.st.UserTx(ctx, f.userID, func(tx *UserTx) error {
			var e error
			keys, e = tx.ContactKeysFor(ctx, contact)
			return e
		}); err != nil {
			t.Fatal(err)
		}
		if len(keys) != 1 {
			t.Fatalf("contact holds %d keys, want exactly 1 (a renewal is not a new key)", len(keys))
		}
		return keys[0]
	}
	usableAfter := func(pub []byte, at time.Time) bool {
		v, err := pgpkeys.Assess(pub, at)
		return err == nil && v.Usable(at)
	}
	contactChanges := func() int { return countChanges(t, f.h, f.userID.String(), "Contact") }

	if !upsert(old, ContactKeyAutocrypt) {
		t.Fatal("first sighting not reported as created")
	}
	if err := f.st.UserTx(ctx, f.userID, func(tx *UserTx) error {
		return tx.SetContactKeyPin(ctx, addr, fpr, ContactKeyAutocrypt)
	}); err != nil {
		t.Fatal(err)
	}
	before := contactChanges()

	if upsert(renewed, ContactKeyWKD) {
		t.Error("a renewal was reported as a NEW key")
	}
	k := stored()
	if !usableAfter(k.PublicKey, now.Add(30*lcDay)) {
		t.Fatal("after the renewal arrived, the stored key still stops working at the OLD expiry")
	}
	if k.Source != ContactKeyAutocrypt {
		t.Errorf("a re-sighting changed the source to %q", k.Source)
	}
	if got := contactChanges() - before; got != 1 {
		t.Errorf("Contact change rows for a merging renewal = %d, want 1", got)
	}
	if err := f.st.UserTx(ctx, f.userID, func(tx *UserTx) error {
		pin, ok, err := tx.ContactKeyPin(ctx, addr)
		if err != nil || !ok || pin != fpr {
			t.Errorf("the pin moved on a renewal: %q ok=%v err=%v", pin, ok, err)
		}
		return nil
	}); err != nil {
		t.Fatal(err)
	}

	// A replay of the old copy, and a repeat of the renewal: no change, no row.
	mid := contactChanges()
	upsert(old, ContactKeyAutocrypt)
	upsert(renewed, ContactKeyWKD)
	if !usableAfter(stored().PublicKey, now.Add(30*lcDay)) {
		t.Error("replaying the old copy shortened the stored key")
	}
	if got := contactChanges() - mid; got != 0 {
		t.Errorf("no-op merges wrote %d Contact change rows, want 0", got)
	}

	// A revocation arrives; then the pre-revocation copy is replayed.
	if err := e.RevokeKey(packet.KeySuperseded, "", nil); err != nil {
		t.Fatal(err)
	}
	upsert(lcPub(t, e), ContactKeyAutocrypt)
	upsert(renewed, ContactKeyAutocrypt)
	upsert(old, ContactKeyAutocrypt)
	// Read at the CURRENT time: the revocation was made after `now` was taken,
	// and a signature created after the moment asked about does not count yet,
	// so reading at `now` failed whenever the test crossed a second boundary.
	if v, err := pgpkeys.Assess(stored().PublicKey, time.Now()); err != nil || !v.Revoked {
		t.Errorf("the revocation did not survive a replay of the pre-revocation copy (err=%v)", err)
	}
}

// TestContactKeyImportMergesRatherThanReplaces: the user pasting an old export
// of a key we already hold renewed must not shorten it.
func TestContactKeyImportMergesRatherThanReplaces(t *testing.T) {
	f := newContactKeyFixture(t)
	ctx := context.Background()
	const addr = "importer@example.com"
	contact := f.seedContact(t, addr)
	now := time.Now().UTC().Truncate(time.Second)

	e := lcGenKey(t, addr, now.Add(-300*lcDay), 310*lcDay)
	old := lcPub(t, e)
	fpr := lcFpr(t, old)
	lcRenew(t, e, now.Add(-time.Hour), 3*365*lcDay)
	renewed := lcPub(t, e)

	// Old copy held first (Autocrypt), then the user imports the renewal, then
	// pastes the old export again. Each import is ONE logical Contact change —
	// the merge inside it must not add a second row.
	if err := f.st.UserTx(ctx, f.userID, func(tx *UserTx) error {
		_, e := tx.UpsertContactKey(ctx, ContactKeyRow{
			ContactID: contact, Kind: KeyPGP, Fingerprint: fpr, PublicKey: old, Source: ContactKeyAutocrypt,
		})
		return e
	}); err != nil {
		t.Fatalf("seed: %v", err)
	}
	for i, pub := range [][]byte{renewed, old} {
		before := countChanges(t, f.h, f.userID.String(), "Contact")
		if err := f.st.UserTx(ctx, f.userID, func(tx *UserTx) error {
			return tx.ImportContactKey(ctx, contact, addr, ContactKeyRow{Fingerprint: fpr, PublicKey: pub})
		}); err != nil {
			t.Fatalf("import: %v", err)
		}
		if got := countChanges(t, f.h, f.userID.String(), "Contact") - before; got != 1 {
			t.Errorf("import %d wrote %d Contact change rows, want exactly 1", i, got)
		}
	}
	var keys []ContactKey
	if err := f.st.UserTx(ctx, f.userID, func(tx *UserTx) error {
		var e error
		keys, e = tx.ContactKeysFor(ctx, contact)
		return e
	}); err != nil {
		t.Fatal(err)
	}
	if len(keys) != 1 {
		t.Fatalf("%d keys", len(keys))
	}
	if v, err := pgpkeys.Assess(keys[0].PublicKey, now.Add(30*lcDay)); err != nil || !v.Usable(now.Add(30*lcDay)) {
		t.Error("importing the OLD copy over a held renewal shortened it — import replaced instead of merging")
	}
}
